const directions = [_][2]i32{ .{ -1, 0 }, .{ 0, 1 }, .{ 1, 0 }, .{ 0, -1 } };
var r: i32 = 5;
var c: i32 = 5;
var d: usize = 0;
    const rr: usize = @intCast(r);
    const cc: usize = @intCast(c);
    d = (d + (if (black[rr][cc]) @as(usize, 3) else 1)) % 4;
    black[rr][cc] = !black[rr][cc];
    r = @mod(r + directions[d][0], 11);
    c = @mod(c + directions[d][1], 11);
